export const MARKER = "Generated by wp2emdash scaffold";

export interface ClientRepoInput {
	name: string;
	slug: string;
	/** The WordPress site being replaced. */
	sourceUrl: string;
	productionUrl: string;
	workerName: string;
	/**
	 * Opt-in staging environment (a second Worker with its own data). Default false: one environment, production, on
	 * its workers.dev address until go-live (src/core/environments.ts).
	 */
	staging?: boolean;
	/** Production's workers.dev address (cloudflare.json → production.worker.url). */
	workersDevUrl?: string;
	/** Single environment: when CI deploys production on a push to main ("prelaunch" = only until go-live). */
	ciDeploy?: "prelaunch" | "always" | "manual";
	/** Test inbox (email.stagingTo): staging's recipients, and the single environment's off-domain (test) messages. */
	testTo?: string[];
	stagingUrl?: string;
	/** Fingerprint `emdash migrate --status` prints for the staging D1: lets CI apply migrations without a prompt. */
	stagingFingerprint?: string;
	productionFingerprint?: string;
	/** Traffic has been switched to this site (after cutover). */
	productionReady: boolean;
	sections: { slug: string; label: string; description: string }[];
	forms: { id: string; title: string; fields: string[]; withheld: string[] }[];
	/** Forms with file upload fields: how long files and their download links are kept (days). */
	formUploads?: number;
	/** Some form has conditional fields or steps. */
	formLogic?: boolean;
	/** Password-protected pages/posts carried behind the password page (src/transform/protected.ts). */
	protectedPages?: number;
	email: { provider: string; from?: string; to: string[] };
	turnstileProduction: boolean;
	/** Messages kept in Workers KV when email cannot be sent (days kept; hold = keep all, send none). */
	outbox?: { days: number; hold: boolean; keepSent?: boolean };
	/** Chat notifications for form messages (kit.config forms.chat, on by default with the outbox). */
	formChat?: boolean;
	/** CRM / mailing-list sync (kit.config forms.crm; with the outbox, never on sensitiveData sites): pre-selected providers. */
	formCrm?: { providers: string[]; brevoEmailKey: boolean };
	/** Tracking carried over from the old site (Google tag ids, Tag Manager container, Cloudflare beacon token). */
	analytics?: LegacyAnalytics;
	/** Analytics is managed in SEO & Analytics (@wp2emdash/seo): tracking codes, conversion events, Visits. */
	analyticsAdmin?: boolean;
	/** Branded sharing cards (@wp2emdash/og) are on. */
	ogCards?: boolean;
	/** SEO panel in the page editor (@wp2emdash/seo) is on. */
	seoPanel?: boolean;
	/** Performance package (kit.config performance): route cache + warm-up after deploy (src/scaffold/perf.ts). */
	routeCache?: boolean;
	/** Site health & monthly report (@wp2emdash/health): default recipients and the report footer. */
	health?: { alertsTo: string[]; reportTo: string[]; footer: string };
	/** Privacy & consent (@wp2emdash/consent): the banner mode it starts with, and consent tools kept from the old site. */
	consent?: { mode: string; keptTools?: string[] };
	/** Backups & Restore (@wp2emdash/backups): alert recipients, retention, off-site copy, production D1 name. */
	backups?: { alertsTo: string[]; daily: number; monthly: number; offsite: boolean; database?: string; restoreTestDays?: number };
	/** Media Assistant (@wp2emdash/media): AI alt text, upload queue, largest original (docs/media.md). */
	media?: MediaDocInput;
	/** Change requests (@wp2emdash/change-requests): retention and whether a webhook feeds the agency tracker. */
	changeRequests?: ChangeRequestsDocInput;
	/** Motion (@wp2emdash/motion): the panel is on; what "as the site was built" means for entrances. */
	motion?: { siteEntrance: "calm" | "standard" };
	sensitiveData: boolean;
	stack: Record<string, string>;
	/** Blog sites: the posts page, archive bases and feed (docs/writing-posts.md). */
	blog?: { index: string; archives: { label: string; base: string }[]; authorBase?: string; feedFull: boolean };
	/** Collections made from WordPress custom post types (docs/editing-custom-content.md). */
	collections?: { label: string; labelSingular: string; slug: string; archive?: string; base?: string; fields: { label: string; type: string }[]; hierarchical: boolean; taxonomies: string[]; shop?: { checkout: "external" | "stripe-payment-links" | "contact"; contactPath?: string } }[];
	/** WordPress comments migrated or a comment form on (docs/moderating-comments.md): per collection, counts only. */
	comments?: { collections: { slug: string; form: boolean; moderation: "all" | "first_time" | "none"; closedAfterDays: number; approved: number }[]; turnstile: boolean };
	/** WordPress users to invite (src/transform/users.ts): counts per EmDash role only — names and emails never reach the repo. */
	invites?: Record<string, number>;
}

const md = (body: string) => `<!-- ${MARKER}. Delete this line to take the file over: later scaffold runs then leave it alone. -->\n${body.trim()}\n`;
const yml = (body: string) => `# ${MARKER}. Delete this line to take the file over: later scaffold runs then leave it alone.\n${body.trim()}\n`;

/**
 * Go-live checklist steps the migration cannot do for the owner: past form entries (never read by the kit: they stay in
 * WordPress until the owner exports them) and the team's accounts (invited by the owner; passwords never migrate).
 */
export function goLiveExtras(i: Pick<ClientRepoInput, "invites">): string {
	const roles = Object.entries(i.invites ?? {}).filter(([, n]) => n > 0);
	const people = roles.reduce((n, [, c]) => n + c, 0);
	return [
		"- [ ] Form entries exported from WordPress by the owner (each form plugin's **Entries → Export**, CSV) and kept somewhere safe outside the site: the migration never reads them, and they are gone once WordPress hosting is retired",
		`- [ ] Team accounts: the owner invites the people who edit the site (admin → **Users** → **Invite**)${people ? ` — ${people} from the old site (${roles.map(([r, n]) => `${n} ${r.toLowerCase()}`).join(", ")}), listed in the invite checklist handed over separately (names and e-mail addresses are never stored in this repository)` : ""}. WordPress passwords do not move: each person sets up their own sign-in from the invite`,
	].join("\n") + "\n";
}

/**
 * Package scripts the docs and CI rely on (scaffold writes them into package.json). None is named "deploy": that is a
 * pnpm built-in command. Single environment (default): production only, plus the Workers preview-URL review step
 * (versions:upload → versions:deploy). Opt-in staging: the staging scripts as well (unchanged for existing sites).
 */
export function deployScripts(o: { staging: boolean; stagingFingerprint?: string | undefined; productionFingerprint?: string | undefined }): Record<string, string> {
	const stg = "--wrangler-config wrangler.jsonc --wrangler-env staging";
	const prod = "--wrangler-config wrangler.jsonc";
	return {
		...(o.staging
			? {
					"build:staging": "CLOUDFLARE_ENV=staging astro build",
					"migrate:staging": `emdash migrate ${stg}`,
					"deploy:staging": `CLOUDFLARE_ENV=staging astro build && emdash migrate ${stg} && wrangler deploy && emdash migrate --check ${stg}`,
					// Same steps without the confirmation prompt: the expected target is pinned, so a wrong database fails instead of asking.
					...(o.stagingFingerprint ? { "ci:deploy:staging": `CLOUDFLARE_ENV=staging astro build && emdash migrate ${stg} --expected-target-fingerprint=${o.stagingFingerprint} && wrangler deploy && emdash migrate --check ${stg}` } : {}),
				}
			: {}),
		"deploy:production": `astro build && emdash migrate ${prod} && wrangler deploy && emdash migrate --check ${prod}`,
		...(o.productionFingerprint ? { "ci:deploy:production": `astro build && emdash migrate ${prod} --expected-target-fingerprint=${o.productionFingerprint} && wrangler deploy && emdash migrate --check ${prod}` } : {}),
		...(o.staging
			? {}
			: {
					// Review step for code changes once production is live: upload a version WITHOUT sending traffic to it; Wrangler
					// prints its preview URL (<version>-<worker>.<subdomain>.workers.dev; preview_urls is on in wrangler.jsonc).
					// No migration here: the preview shares production's D1, R2 and KV (data), so it is for code and layout review.
					"versions:upload": "astro build && wrangler versions upload",
					// Promote a reviewed version: migrations first (as deploy:production). Becomes scripts/versions-deploy.mjs (versionsDeployScript): `pnpm versions:deploy <version-id>`.
					// With the recorded fingerprint, unattended (emdash migrate refuses a noninteractive apply without it, even when
					// nothing is pending: found 2026-11-24); without one it asks, so run it from a terminal.
					"versions:deploy": `emdash migrate ${prod}${o.productionFingerprint ? ` --expected-target-fingerprint=${o.productionFingerprint}` : ""} && wrangler versions deploy`,
				}),
	};
}

