/** Write the files, skipping any a person has taken over (marker removed). Returns the paths left alone. */
export function writeClientRepo(project: string, files: Record<string, string>): string[] {
	const kept: string[] = [];
	for (const [rel, content] of Object.entries(files)) {
		const file = join(project, rel);
		if (existsSync(file) && !readFileSync(file, "utf8").split("\n", 3).some((l) => l.includes(MARKER))) {
			kept.push(rel);
			continue;
		}
		mkdirSync(dirname(file), { recursive: true });
		writeFileSync(file, content);
	}
	return kept;
}

const FIELD_HELP: Record<string, string> = {
	string: "a line of text",
	text: "plain text, several lines",
	url: "a web address (https://…, mailto:, tel: or a /path on the site)",
	number: "a number",
	integer: "a whole number",
	boolean: "on or off",
	datetime: "a date (and time)",
	select: "one choice from a list",
	multiSelect: "several choices from a list",
	portableText: "formatted text (headings, lists, links, images)",
	image: "an image from the media library",
	file: "a file from the media library",
	reference: "a link to another entry (picked from a list)",
	repeater: "a list of rows; add, remove and reorder rows",
	json: "data kept exactly as WordPress stored it (edit with care, or ask your developer)",
};

const MODERATION_HELP = { all: "every new comment waits for approval", first_time: "a visitor's first comment waits for approval; once one of theirs is approved, the next ones appear straight away", none: "new comments appear straight away (spam protection still runs)" } as const;

/** docs/moderating-comments.md: where comments are, how to moderate them, what the form does with visitors' data. */
export function commentsGuide(c: NonNullable<ClientRepoInput["comments"]>): string {
	const rows = c.collections.map((x) => `| ${x.slug} | ${x.approved} | ${x.form ? `on — ${MODERATION_HELP[x.moderation]}` : "off (comments are shown, no new ones)"} | ${x.form ? (x.closedAfterDays ? `${x.closedAfterDays} days after publishing` : "never") : "—"} |`).join("\n");
	const anyForm = c.collections.some((x) => x.form);
	return `
# Moderating comments

The comments your WordPress site had are here, under the same posts, with their original date and author name. Replies
are kept one level deep: an answer to an answer sits in the same thread as the first answer.

| Collection | Comments migrated | Comment form | Closes |
|---|---|---|---|
${rows}

## Where they are

Admin → **Comments**. The tabs are **Pending** (waiting for you), **Approved** (shown on the site), **Spam** and
**Trash**. Each comment shows its author, the entry it belongs to and the text. Tick several and use the bulk buttons
to approve, mark as spam or move to the trash; **Delete** removes a comment for good (its replies go with it).

An approved comment shows on the page within a moment: approving clears the page from the cache.

${anyForm ? `## New comments

Visitors comment with a name, an e-mail address and the text. ${c.turnstile ? "A Cloudflare Turnstile check (usually invisible) stops automated posting; " : ""}a hidden trap field catches simple bots, and one visitor can post at most five comments in ten minutes. Depending on the setting above, a new comment either appears straight away or waits in **Pending**.

- **Close comments on one entry:** open it and tick **Comments closed**. Its comments still show; the form disappears and
  new comments are refused.
- **Change the rules for all entries** (approval, closing after a number of days, the form on or off): ask your
  developer — these are collection settings.

## Visitors' data

A commenter's e-mail address is stored with the comment so you can tell repeat commenters apart; it is never shown on
the site, and the kit never copies it into reports or logs. The IP address is not stored (only a one-way fingerprint
used for the rate limit). The form says so next to the button and links to your privacy policy. When someone asks for
their comments to be removed, find them in **Comments** (search by name or address) and delete them.
` : `## No new comments

The comment form is off: the site shows the migrated comments, and visitors cannot add new ones. Ask your developer to
switch it on.
`}
## Backups

Comments are not in the nightly backups (they hold visitors' personal data). Cloudflare D1 Time Travel (30 days)
restores the whole database, comments included, if something goes badly wrong — ask your developer.
`;
}

/** Editor guide, shop sites only: how to fill in the product grid section (WooCommerce catalogue mode). */
function productGridHelp(): string {
	return `
**Product grid** (shop sites): add it to any page (for example "Featured products" on the home page) and choose
**Which products**: \`latest\` (newest first), \`on_sale\` (products with a sale price), \`category\` (fill in
**Product categories** with the category slugs, e.g. \`mugs, bowls\`) or \`handpicked\` (fill in **Products** with the
product addresses, e.g. \`/product/blue-mug/, /product/green-bowl/\`, shown in that order). **How many** (1–12, 4 by
default), **Products per row**, **Show the price** and **Button label** (empty: each product's own Buy button text,
else "View product") finish it. The cards are the shop's own product cards and link to the product pages; the grid
updates on its own when a product is published, changed or put on sale.
`;
}

/** docs/editing-custom-content.md: one section per collection made from a WordPress custom post type. */
/** The products collection (WooCommerce catalogue mode): what the Buy button does and what the shop no longer has. */
function shopHelp(shop: { checkout: "external" | "stripe-payment-links" | "contact"; contactPath?: string }): string {
	const buy =
		shop.checkout === "contact"
			? `The **Buy** button opens the contact form${shop.contactPath ? ` (\`${shop.contactPath}\`)` : ""} with the product's name already in the message. Products from another shop (external products) keep their own **Buy link**.`
			: shop.checkout === "stripe-payment-links"
				? "The **Buy** button goes to the product's **Buy link**: paste the product's Stripe Payment Link there (Stripe Dashboard → Payment Links → New; one link per product, or per option for products with options). **Buy button text** changes the label."
				: "The **Buy** button goes to the product's **Buy link**: paste the address of the product in your checkout (your online store, booking or payment page). **Buy button text** changes the label.";
	return `**Selling.** There is no cart or customer account on this site. ${buy} A product without a Buy link shows an **Enquire** button to the contact form when the site has one. **Availability** "Out of stock" turns the button off. **Sale price**: clear it to end a sale. Stock levels, coupons and orders live in the checkout, not here.`;
}

export function customContentGuide(cols: NonNullable<ClientRepoInput["collections"]>): string {
	const parts = cols.map((c) => {
		const rows = c.fields.map((f) => `| ${f.label} | ${FIELD_HELP[f.type] ?? f.type} |`).join("\n");
		return `## ${c.label}

${c.archive ? `Listed at \`${c.archive}\` (newest first${c.hierarchical ? "; entries keep their order and parent" : ""}, numbered pages \`${c.archive}page/2/\`). ` : ""}${c.base ? `Each ${c.labelSingular.toLowerCase()} has its own page at \`${c.base}<slug>/\`.` : `${c.label} have no pages of their own: they are shown inside other pages.`}${c.taxonomies.length ? ` Grouped by ${c.taxonomies.join(", ")} (side panel); each group has its own page.` : ""}

| Field | What it holds |
|---|---|
| Title | the ${c.labelSingular.toLowerCase()}'s name or heading |
${rows}${c.shop ? `\n\n${shopHelp(c.shop)}` : ""}`;
	});
	return `
# Editing custom content

Content that WordPress kept as its own type (team members, services, projects…) is a collection here, with the same
fields it had in WordPress. Every entry is in the admin under the collection's name, at the same address as before.

## A new entry

1. Open the collection in the admin sidebar → **New**. Fill in the title and the fields (below).
2. **Slug** is the address. Migrated entries keep their WordPress address as their slug (for example \`team/jane-doe\`);
   do not change it, or old links break. A new entry's slug should start the same way (\`team/new-person\`) so it
   appears under the same address.
3. **Featured image**, **Excerpt** and **Order** (where the collection has them): the picture and short text on the
   listing, and the position among the others.
4. **SEO** (side panel): title, description and sharing image, as for pages.
5. **Publish**. The listing and the entry's page update within a moment (publishing clears the cached pages).

Entries built with a page builder on WordPress keep their sections in **Sections**; new entries only need the fields.
Fields marked *data kept as WordPress stored it* had no matching field type: they show on the page as a list, and your
developer can turn them into proper fields later.

${parts.join("\n\n")}
`;
}

/**
 * `pnpm versions:deploy <version-id>`: the reviewed version goes live without a prompt. The chain (migrations, then
 * `wrangler versions deploy`, then the warm-up and deploy check appended by withWarmup/withDeployCheck) moves into
 * scripts/versions-deploy.mjs, which puts the version where Wrangler reads it: appended to the package.json script, the
 * id landed on the deploy check and `wrangler versions deploy` asked which version (an interactive prompt; found
 * 2026-11-23 on a live EmDash upgrade).
 */
export function versionsDeployScript(scripts: Record<string, string>, o: { accountId?: string } = {}): { scripts: Record<string, string>; file?: string } {
	const chain = scripts["versions:deploy"];
	if (!chain || !/\bwrangler versions deploy\b/.test(chain)) return { scripts };
	const account = o.accountId && /^[0-9a-f]{32}$/i.test(o.accountId) ? o.accountId : undefined;
	const file = `#!/usr/bin/env node
// Generated by wp2emdash scaffold. Usage: pnpm versions:deploy <version-id>   (the id \`pnpm versions:upload\` printed)
// Sends all traffic to that reviewed version: migrations first, then \`wrangler versions deploy <id>@100% --yes\`, then
// the warm-up and the deploy check, in this order; any failing step stops the rest.
//
// Credentials (\`emdash migrate\` needs both; nothing is printed): what the shell already has, else this project's .env,
// else the account this site was provisioned in and the token of your \`wrangler login\` (\`wrangler auth token\`).
import { spawnSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";

const CHAIN = ${JSON.stringify(chain)};
const ACCOUNT = ${JSON.stringify(account ?? "")};
const arg = process.argv[2] ?? "";
const id = arg.replace(/@\\d+%$/, "");
if (!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(id)) {
	console.error("Usage: pnpm versions:deploy <version-id>   (the Worker Version ID printed by pnpm versions:upload)");
	process.exit(1);
}
if (existsSync(".env"))
	for (const line of readFileSync(".env", "utf8").split(/\\r?\\n/)) {
		const m = /^\\s*(?:export\\s+)?([A-Za-z_][A-Za-z0-9_]*)\\s*=\\s*(.*?)\\s*$/.exec(line);
		if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].replace(/^(["'])(.*)\\1$/, "$2");
	}
if (!process.env.CLOUDFLARE_ACCOUNT_ID && ACCOUNT) process.env.CLOUDFLARE_ACCOUNT_ID = ACCOUNT;
if (!process.env.CLOUDFLARE_API_TOKEN) {
	const r = spawnSync("npx", ["wrangler", "auth", "token", "--json"], { encoding: "utf8", shell: process.platform === "win32" });
	try {
		const t = JSON.parse(r.stdout.slice(r.stdout.indexOf("{")));
		if (typeof t.token === "string" && t.token) process.env.CLOUDFLARE_API_TOKEN = t.token;
	} catch {}
}
const missing = ["CLOUDFLARE_ACCOUNT_ID", "CLOUDFLARE_API_TOKEN"].filter((k) => !process.env[k]);
if (missing.length) {
	console.error(\`Missing \${missing.join(" and ")}: run \\\`npx wrangler login\\\` (or put them in .env), then try again.\`);
	process.exit(1);
}
for (const step of CHAIN.split(" && ")) {
	const cmd = step.replace(/\\bwrangler versions deploy\\b/, \`wrangler versions deploy \${id}@100% --yes\`);
	console.log(\`> \${cmd}\`);
	const r = spawnSync(cmd, { stdio: "inherit", shell: true });
	if (r.status !== 0) process.exit(r.status ?? 1);
}
`;
	return { scripts: { ...scripts, "versions:deploy": "node scripts/versions-deploy.mjs" }, file };
}
